INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63244672', 63244672, 'analyze_legacy', 'Badan Narkotika Nasional', 'central', 'BADAN NARKOTIKA NASIONAL KABUPATEN SIDOARJO', 'Tenaga Alih Daya Bulan Feb-Des 2026 (dan THR)', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 192400000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PKT', 'Pengadaan tenaga alih daya pada Bulan Januari di lingkungan Badan Narkotika Nasional Kabupaten (BNNK) Sidoarjo dilaksanakan untuk mendukung kelancaran pelaksanaan tugas dan fungsi organisasi secara optimal. Tenaga alih daya yang disediakan terdiri atas Dua orang Satuan Pengamanan (Satpam), satu orang Pengemudi, dan Satu orang Tenaga Kebersihan. Keberadaan tenaga tersebut berperan penting dalam menjaga keamanan, mendukung mobilitas operasional, serta menciptakan lingkungan kerja yang bersih, tertib, dan nyaman bagi seluruh pegawai dan masyarakat penerima layanan.', 'Tenaga Satuan Pengamanan bertugas melaksanakan pengamanan dan menjaga ketertiban di lingkungan kantor BNNK Sidoarjo. Satpam bertanggung jawab melakukan pengawasan terhadap seluruh aktivitas di area kantor, mengatur keluar masuk pegawai, tamu, dan kendaraan, serta memastikan bahwa setiap orang yang memasuki lingkungan kantor telah sesuai dengan ketentuan yang berlaku. Selain itu, Satpam melaksanakan patroli rutin untuk mengantisipasi potensi gangguan keamanan, menjaga aset dan sarana prasarana kantor, serta memastikan situasi lingkungan kerja tetap aman dan kondusif. Satpam juga wajib melaporkan setiap kejadian yang berpotensi mengganggu keamanan dan ketertiban kepada pimpinan atau petugas yang berwenang, serta memberikan dukungan pengamanan pada kegiatan kedinasan yang diselenggarakan oleh BNNK Sidoarjo. Tenaga Pengemudi berperan dalam mendukung kelancaran mobilitas operasional dan pelaksanaan kegiatan kedinasan BNNK Sidoarjo. Pengemudi bertugas mengemudikan kendaraan dinas sesuai dengan penugasan pimpinan untuk keperluan operasional kantor, koordinasi, dan kegiatan luar kantor lainnya. Dalam pelaksanaan tugasnya, Pengemudi wajib mematuhi peraturan lalu lintas serta mengutamakan keselamatan, ketertiban, dan kenyamanan selama perjalanan. Selain mengemudikan kendaraan, Pengemudi juga bertanggung jawab menjaga kebersihan dan kondisi kendaraan agar selalu dalam keadaan layak pakai, melakukan pemeriksaan rutin kendaraan, serta mencatat penggunaan kendaraan pada buku log. Setiap kerusakan atau kebutuhan perawatan kendaraan harus segera dilaporkan kepada penanggung jawab sarana dan prasarana. Tenaga Kebersihan sebanyak dua orang bertugas menjaga kebersihan, kerapian, dan kenyamanan seluruh lingkungan kerja BNNK Sidoarjo. Lingkup pekerjaan Tenaga Kebersihan meliputi pembersihan ruang kerja, ruang pelayanan, ruang rapat, lorong, toilet, dan area pendukung lainnya secara rutin dan berkala. Tenaga Kebersihan melakukan kegiatan menyapu, mengepel, membersihkan kaca, mengelola sampah, serta memastikan fasilitas umum selalu dalam kondisi bersih dan higienis. Selain itu, Tenaga Kebersihan mendukung kebersihan selama pelaksanaan kegiatan atau acara kedinasan serta menggunakan peralatan dan bahan kebersihan secara efektif dan bertanggung jawab. Apabila terdapat kekurangan alat atau bahan kebersihan, Tenaga Kebersihan wajib melaporkannya kepada penanggung jawab. Secara keseluruhan, pengadaan tenaga alih daya ini diharapkan mampu mendukung terciptanya lingkungan kerja BNNK Sidoarjo yang aman, tertib, bersih, dan kondusif sehingga pelaksanaan tugas dan pelayanan kepada masyarakat dapat berjalan secara optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 830172);
