INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62744953', 62744953, 'analyze_legacy', 'Kota Bandung', 'kabkota', 'Bagian Umum', 'BELANJA JASA TENAGA KEAMANAN GEDUNG KANTOR PKK DAN DHARMAWANITA KOTA BANDUNG BULAN JANUARI - NOVEMBER', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 422154962, 'January 2026', 'APBD', 1, 1, '6 Orang x 11 Bulan', 'BELANJA JASA TENAGA KEAMANAN GEDUNG KANTOR PKK DAN DHARMAWANITA KOTA BANDUNG BULAN JANUARI - NOVEMBER', 'Spesifikasi Teknis a) Spesifikasi teknis untuk masing-masing Penyedia adalah sebagai berikut : 1. Memiliki kelengkapan adminitrasi Penyedia Jasa Tenaga Keamanan lengkap dan masih berlaku serta terdaftar di kepolisian; 2. Perusahan terdaftar sebagai anggota BPJS Kesehatan maupun BPJS Ketenagakerjaan; 3. Memiliki pengalaman di bidang pengamanan di instansi pemerintahan; 4. Sudah siap personil. b) Kebutuhan Personil 1. Laki‐laki, usia 20-50 tahun; 2. Perempuan, usia 20-50 tahun; 3. Pendidikan minimum SMP / sederajat diutamakan SMA / sederajat; 4. Tinggi minimal laki-laki 160 dan berat badan ideal; 5. Tinggi minimal perempuan 155 dan berat badan ideal; 6. Berbadan sehat dan memiliki kondisi fisik yang baik dibuktikan dengan surat keterangan sehat; 7. Berkelakuan baik, tidak pernah terlibat masalah hukum yang dibuktikan dengan SKCK dari kepolisian; 8. Memiliki pengetahuan tentang pengamanan; 9. Diutamakan memiliki sertifikat Gada Pratama; 10. Memiliki KTA Satpam. c) Kebutuhan Non Personil 1. Pakaian Seragam yang menunjang; 2. Peralatan kerja yang menunjang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 831067);
