INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62746749', 62746749, 'analyze_legacy', 'Provinsi Jawa Tengah', 'provinsi', 'BADAN PERENCANAAN PEMBANGUNAN DAERAH', 'Belanja Suvenir Peserta Kegiatan - Subbid Penyusunan Program', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 50000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Suvenir Peserta Kegiatan - Subbid Penyusunan Program', 'Belanja Suvenir Peserta Kegiatan - Subbid Penyusunan Program', 50000000, 'high', 'Pengadaan suvenir untuk peserta kegiatan pada unit perencanaan pembangunan terindikasi tidak esensial terhadap fungsi inti dan berisiko menjadi belanja seremonial. Berdasarkan judul dan spesifikasi yang sangat umum, seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 835171);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63268156', 63268156, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Junior Penyusunan Kebijakan Integrasi Penataan Ruang Kegiatan Koordinasi Penyusunan Rencana Kerja Pemerintah (RKP) Bidang Tata Ruang, Perkotaan, Pertanahan, Informasi Geospasial, Dan Penanggulangan Bencana (TRP3BIG) Tahun 2027 Direktorat Tata Ruang, Perkotaan, Pertanahan Dan Penanggulangan Bencana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 144015000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Mengidentifikasi dan analisis isu strategis integrasi penataan ruang seluruh matra. 2. Melakukan inventarisasi dan analisis regulasi serta kebijakan terkait integrasi penataan ruang. 3. Menganalisis isu dan tantangan implementasi kebijakan integrasi penataan ruang seluruh matra. 4. Menganalisis keterkaitan integrasi penataan ruang dengan RPJMN dan RKP. 5. Merumuskan strategi dan rekomendasi kebijakan integrasi penataan ruang seluruh matra. 6. Membantu tim dalam melakukan koordinasi di internal Kementerian PPN/Bappenas maupun dengan K/L terkait; 7. Membantu tim dalam lingkup pekerjaan lain yang berkaitan dengan isu-isu tata ruang, baik nasional maupun daerah; serta', '1. Merupakan Jasa Konsultan Individual dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Sarjana minimal (S-1) bidang Perencananaan Wilayah dan Kota (dibuktikan dengan ijazah); 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 2 (dua) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; 5. Memiliki pengalaman dalam bidang penyusunan strategi, kebijakan, dan perencanaan bidang tata ruang dan kewilayahan minimal 2 (dua) tahun dibuktikan dengan kontrak kerja/referensi; 6. Memiliki pengalaman melaksanakan koordinasi antar stakeholder terutama Pemerintahan (Kementerian/Lembaga/Daerah); 7. Memiliki pengalaman organisasi, pengelolaan proyek, dan mampu bekerja di dalam tim;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 835172);
