INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63296473', 63296473, 'analyze_legacy', 'Kab. Probolinggo', 'kabkota', 'Dinas Pertanian', 'Pengadaan Obat-Obatan-Obat-Obatan Lainnya (Pengawasan atas Penerapan Persyaratan Teknis untuk Pemasukan dan/atau Pengeluaran Hewan, Produk Hewan dan Media Pembawa Penyakit Hewan Lainnya (HPM), PAD', 'Barang', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 11100000, 'February 2026', 'APBD', 1, 1, '1 Paket', '- Vaksin ND = 50 Botol - Vitastress = 100 Sachet - Vita Tetra Chlor = 300 Kapsul', '- Vaksin ND Spesifikasi : Vaksin ND LS VAC 1000 dosis merupakan vaksin aktif kering beku yang mengandung virus Newcastle Disease (ND) strain La Sota yang dilemahkan. Dosis: Setiap vial berisi 1000 dosis, yang berarti satu dosis diberikan per ekor unggas setelah dilarutkan dengan pelarut yang sesuai. - Vitastress Spesifikasi : serbuk oral multivitamin & elektrolit untuk unggas (ayam, bebek, burung) yang berfungsi mencegah stres dan meningkatkan daya tahan tubuh dengan kandungan 11 vitamin (A, D, E, K, B-kompleks, C) serta 4 elektrolit penting, dipakai 1 gram per 1-2 liter air minum untuk berbagai kondisi seperti vaksinasi, perubahan pakan, atau pemulihan pasca-sakit. - Vita Tetra Chlor Spesifikasi : obat ayam dalam bentuk kapsul berisi antibiotik spektrum luas (Tetracycline HCI & Erythromycin) serta vitamin (B kompleks & C) untuk mengobati penyakit pernapasan seperti Korisa (Snot), Kolera (berak hijau), Pullorum (berak kapur), dan CRD (ngorok), juga membantu pemulihan luka dan stres, dengan dosis disesuaikan usia ayam (misal, <4 minggu: 1/2 kapsul/hari).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 839067);
